class UpperStep(BaseStep):
    COMPONENT_TYPE = "upper_step"

    async def process(self, input_data: dict, **kwargs) -> dict:
        text = input_data.get("text")
        if not isinstance(text, str):
            raise ValueError("text must be a string")
        return {"output": text.upper()}

from nanobrain.core.tool import ToolBase

class CalculatorTool(ToolBase):
    async def execute(self, expression: str) -> dict:
        if not expression:
            raise ValueError("Empty expression")
        allowed = set('+-*/() ')
        if any(c not in allowed for c in expression):
            raise ValueError("Invalid character")
        result = eval(expression, {}, {})
        if not isinstance(result, (int, float)):
            raise ValueError("Result not numeric")
        return {"result": result}
